                    scope[A] = cur
                    cur = _s_first_magic(scope, arg, _t)
                else:
                    cur = getattr(cur, arg)
            elif op == '[':
                cur = cur[arg]
            elif op == 'P':
                _get = scope[TargetRegistry].get_handler('get', cur, path=scope[Path])
                cur = _get(cur, arg)
            elif op == '(':
                args, kwargs = arg
                args = arg_val(target, args, scope)
                kwargs = arg_val(target, kwargs, scope)
                cur = cur(*args, **kwargs)
            elif op == 'x':
                scope[Path] += ['*']
                iterate = scope[TargetRegistry].get_handler('iterate', cur, path=scope[Path])
                try:
                    iterator = iterate(cur)
                except Exception as e:
                    raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                                    % (cur.__class__.__name__, Path(*scope[Path]), e))
                ret = []
                base_path = scope[Path]
                for idx, item in enumerate(iterator):
                    scope[Path] = base_path + [idx]
                    ret.append(item)
                scope[Path] = base_path
                cur = ret
            elif op == 'X':
                scope[Path] += ['**']
                children = [cur]
                ret = [cur]
                get_handler = scope[TargetRegistry].get_handler
                while children:
                    new_children = []
                    for child in children:
                        _extend_children(new_children, child, get_handler)
                    ret.extend(new_children)
                    children = new_children
                scope[Path] = scope[Path][:-1]
                cur = ret
            elif op == '+':
                cur = cur + arg_val(target, arg, scope)
            elif op == '-':
                cur = cur - arg_val(target, arg, scope)
            elif op == '*':
                cur = cur * arg_val(target, arg, scope)
            elif op == '/':
                cur = cur / arg_val(target, arg, scope)
            elif op == '#':
                cur = cur // arg_val(target, arg, scope)
            elif op == '%':
                cur = cur % arg_val(target, arg, scope)
            elif op == ':':
                cur = cur ** arg_val(target, arg, scope)
            elif op == '&':
                cur = cur & arg_val(target, arg, scope)
            elif op == '|':
                cur = cur | arg_val(target, arg, scope)
            elif op == '^':
                cur = cur ^ arg_val(target, arg, scope)
            elif op == '~':
                cur = ~cur
            elif op == '_':
                cur = -cur
        except Exception as e:
            if isinstance(e, GlomError):
                raise
            raise PathAccessError(e, Path(_t), (i // 2) - 1)

    return cur


def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', None)
    if scope is None:
        scope = ChainMap(_DEFAULT_SCOPE)
    elif not isinstance(scope, ChainMap):
        scope = ChainMap(scope, _DEFAULT_SCOPE)

